PRAGMA foreign_keys=ON;
CREATE TABLE workspace(id TEXT PRIMARY KEY CHECK(id='workspace'),schema_version INTEGER NOT NULL,build_id TEXT NOT NULL,display_name TEXT NOT NULL,default_timezone TEXT NOT NULL,settings_revision INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE workspace_settings(id TEXT PRIMARY KEY DEFAULT 'workspace',workspace_id TEXT NOT NULL REFERENCES workspace(id),schema_version INTEGER NOT NULL DEFAULT 1,nonsecret_settings_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE templates(id TEXT PRIMARY KEY,name TEXT NOT NULL DEFAULT '',built_in_key TEXT,archived_at INTEGER,current_version_id TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE template_versions(id TEXT PRIMARY KEY,template_id TEXT NOT NULL REFERENCES templates(id) ON DELETE CASCADE,version INTEGER NOT NULL,section_schema_json TEXT NOT NULL DEFAULT '{}',extraction_policy_json TEXT NOT NULL DEFAULT '{}',content_hash TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',UNIQUE(template_id,version));
CREATE TABLE installed_artifacts(id TEXT PRIMARY KEY,catalog_id TEXT NOT NULL,kind TEXT NOT NULL,exact_version TEXT NOT NULL,target TEXT NOT NULL,source_revision TEXT NOT NULL,sha256 TEXT NOT NULL,relative_path TEXT NOT NULL,license_manifest_json TEXT NOT NULL,state TEXT NOT NULL,installed_at INTEGER,last_used_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',UNIQUE(catalog_id,exact_version,target));
CREATE TABLE objects(id TEXT PRIMARY KEY,kind TEXT NOT NULL,relative_path TEXT NOT NULL UNIQUE,sha256 TEXT NOT NULL,bytes INTEGER NOT NULL CHECK(bytes>=0),owning_entity_id TEXT NOT NULL,retained_until INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE projects(id TEXT PRIMARY KEY,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',archived_at INTEGER,default_template_id TEXT REFERENCES templates(id) ON DELETE SET NULL,vocabulary_revision INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE work_packages(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,name TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',archived_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',UNIQUE(project_id,name));
CREATE TABLE meetings(id TEXT PRIMARY KEY,title TEXT NOT NULL,state TEXT NOT NULL CHECK(state IN('draft','starting','recording','paused','stopping','processing','complete','attention_required','interrupted')),health TEXT NOT NULL DEFAULT 'healthy',started_at INTEGER,ended_at INTEGER,elapsed_ms INTEGER NOT NULL DEFAULT 0,active_ms INTEGER NOT NULL DEFAULT 0,project_id TEXT REFERENCES projects(id) ON DELETE SET NULL,work_package_id TEXT REFERENCES work_packages(id) ON DELETE SET NULL,template_version_id TEXT REFERENCES template_versions(id) ON DELETE SET NULL,calendar_event_id TEXT,config_snapshot_json TEXT NOT NULL DEFAULT '{}',policy_hash TEXT NOT NULL DEFAULT '',transcript_revision INTEGER NOT NULL DEFAULT 0,note_revision INTEGER NOT NULL DEFAULT 0,stop_watermark INTEGER,interrupted_reason TEXT,capture_epoch INTEGER NOT NULL DEFAULT 0,active_since INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE UNIQUE INDEX one_capture ON meetings((1)) WHERE state IN('starting','recording','paused','stopping');
CREATE INDEX meeting_history ON meetings(started_at DESC,id DESC);
CREATE INDEX meeting_project ON meetings(project_id,started_at);
CREATE TABLE capture_sources(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,source_kind TEXT NOT NULL,device_key TEXT NOT NULL DEFAULT '',display_name TEXT NOT NULL DEFAULT '',epoch INTEGER NOT NULL DEFAULT 0,state TEXT NOT NULL DEFAULT 'starting',clock_mapping_json TEXT NOT NULL DEFAULT '{}',processing_profile_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE timeline_gaps(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,source_id TEXT REFERENCES capture_sources(id) ON DELETE CASCADE,start_ms INTEGER NOT NULL CHECK(start_ms>=0),end_ms INTEGER,reason TEXT NOT NULL,acknowledged INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',CHECK(end_ms IS NULL OR end_ms>=start_ms));
CREATE TABLE transcript_runs(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,source TEXT NOT NULL DEFAULT 'live',state TEXT NOT NULL DEFAULT 'candidate',provider_fingerprint TEXT NOT NULL DEFAULT '',model_fingerprint TEXT NOT NULL DEFAULT '',language_policy TEXT NOT NULL DEFAULT 'auto',parent_run_id TEXT REFERENCES transcript_runs(id) ON DELETE SET NULL,completed_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE UNIQUE INDEX active_run ON transcript_runs(meeting_id) WHERE state='active';
CREATE TABLE utterances(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,run_id TEXT NOT NULL REFERENCES transcript_runs(id) ON DELETE CASCADE,source_id TEXT REFERENCES capture_sources(id) ON DELETE CASCADE,provider_stream_id TEXT NOT NULL DEFAULT '',provider_result_id TEXT NOT NULL DEFAULT '',start_ms INTEGER NOT NULL CHECK(start_ms>=0),end_ms INTEGER NOT NULL,text TEXT NOT NULL,language TEXT,confidence REAL,is_final INTEGER NOT NULL DEFAULT 1,timing_provenance TEXT NOT NULL DEFAULT 'segment',text_revision INTEGER NOT NULL DEFAULT 1,speaker_revision INTEGER NOT NULL DEFAULT 1,manual_text_lock INTEGER NOT NULL DEFAULT 0,manual_speaker_lock INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',CHECK(end_ms>=start_ms),CHECK(confidence IS NULL OR confidence BETWEEN 0 AND 1),UNIQUE(run_id,source_id,provider_stream_id,provider_result_id));
CREATE INDEX transcript_order ON utterances(meeting_id,run_id,start_ms,id);
CREATE TABLE utterance_revisions(id TEXT PRIMARY KEY,utterance_id TEXT NOT NULL REFERENCES utterances(id) ON DELETE CASCADE,actor TEXT NOT NULL CHECK(actor IN('user','asr','import')),before_json TEXT NOT NULL,after_json TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE meeting_speakers(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,source_kind TEXT NOT NULL DEFAULT 'system',display_name TEXT NOT NULL DEFAULT 'Unknown',color_token TEXT NOT NULL DEFAULT 'speaker-1',person_id TEXT,manual_name_lock INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE words(utterance_id TEXT NOT NULL REFERENCES utterances(id) ON DELETE CASCADE,ordinal INTEGER NOT NULL,text TEXT NOT NULL,start_ms INTEGER,end_ms INTEGER,confidence REAL,speaker_id TEXT REFERENCES meeting_speakers(id) ON DELETE SET NULL,PRIMARY KEY(utterance_id,ordinal),CHECK(start_ms IS NULL OR end_ms>=start_ms));
CREATE TABLE speaker_assignments(id TEXT PRIMARY KEY,utterance_id TEXT NOT NULL REFERENCES utterances(id) ON DELETE CASCADE,speaker_id TEXT NOT NULL REFERENCES meeting_speakers(id) ON DELETE CASCADE,start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL,confidence REAL,origin TEXT NOT NULL DEFAULT 'source',overlap INTEGER NOT NULL DEFAULT 0,manual_lock INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',CHECK(start_ms>=0 AND end_ms>=start_ms));
CREATE TABLE speaker_clusters(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,provider_session_id TEXT NOT NULL,provider_speaker_id TEXT NOT NULL,mapped_speaker_id TEXT REFERENCES meeting_speakers(id) ON DELETE SET NULL,model_fingerprint TEXT NOT NULL,embedding_object_ref TEXT REFERENCES objects(id) ON DELETE SET NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE people(id TEXT PRIMARY KEY,display_name TEXT NOT NULL,notes TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE voice_profiles(id TEXT PRIMARY KEY,person_id TEXT NOT NULL REFERENCES people(id) ON DELETE CASCADE,model_fingerprint TEXT NOT NULL,vector_object_ref TEXT NOT NULL REFERENCES objects(id) ON DELETE CASCADE,consent_at INTEGER NOT NULL,last_seen_at INTEGER,matching_scope_json TEXT NOT NULL,enabled INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE notes(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,heading TEXT NOT NULL DEFAULT '',body_markdown TEXT NOT NULL DEFAULT '',ordinal INTEGER NOT NULL DEFAULT 0,anchor_utterance_id TEXT REFERENCES utterances(id) ON DELETE SET NULL,anchor_ms INTEGER,provenance TEXT NOT NULL DEFAULT 'human' CHECK(provenance='human'),created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE note_revisions(id TEXT PRIMARY KEY,note_id TEXT NOT NULL REFERENCES notes(id) ON DELETE CASCADE,meeting_note_revision INTEGER NOT NULL,heading TEXT NOT NULL,body_markdown TEXT NOT NULL,ordinal INTEGER NOT NULL,anchor_utterance_id TEXT,anchor_ms INTEGER,actor TEXT NOT NULL DEFAULT 'user',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE important_moments(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,utterance_id TEXT REFERENCES utterances(id) ON DELETE SET NULL,start_ms INTEGER NOT NULL DEFAULT 0,label TEXT NOT NULL DEFAULT '',quote_snapshot TEXT NOT NULL DEFAULT '',note TEXT NOT NULL DEFAULT '',include_in_minutes INTEGER NOT NULL DEFAULT 1,status TEXT NOT NULL DEFAULT 'open',priority TEXT NOT NULL DEFAULT 'normal',assignee TEXT,due_date TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE actions(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,stable_origin_key TEXT NOT NULL,description TEXT NOT NULL,assignee_person_id TEXT REFERENCES people(id) ON DELETE SET NULL,assignee_text TEXT,due_date TEXT,deadline_text TEXT,timezone TEXT,priority TEXT NOT NULL DEFAULT 'normal' CHECK(priority IN('none','low','normal','high','urgent')),status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','in_progress','done','dismissed')),manual_fields_json TEXT NOT NULL DEFAULT '[]',source_result_id TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',UNIQUE(meeting_id,stable_origin_key));
CREATE INDEX action_followups ON actions(status,due_date,id);
CREATE TABLE questions(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,utterance_id TEXT REFERENCES utterances(id) ON DELETE SET NULL,text TEXT NOT NULL,detection_version TEXT NOT NULL DEFAULT 'en-es-v1',status TEXT NOT NULL DEFAULT 'open' CHECK(status IN('open','answered','dismissed')),answer_utterance_id TEXT REFERENCES utterances(id) ON DELETE SET NULL,answered_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',UNIQUE(utterance_id,detection_version));
CREATE INDEX question_state ON questions(meeting_id,status);
CREATE TABLE cues(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,kind TEXT NOT NULL,text TEXT NOT NULL,source_utterance_id TEXT NOT NULL REFERENCES utterances(id) ON DELETE CASCADE,expires_at INTEGER,dismissed_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE topics(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,parent_id TEXT REFERENCES topics(id) ON DELETE CASCADE,title TEXT NOT NULL,start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL,sentiment TEXT,confidence REAL,result_id TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',CHECK(start_ms>=0 AND end_ms>=start_ms));
CREATE TABLE artifacts(id TEXT PRIMARY KEY,meeting_id TEXT REFERENCES meetings(id) ON DELETE CASCADE,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,kind TEXT NOT NULL CHECK(kind IN('decision','risk','milestone','deliverable','follow_up')),title TEXT NOT NULL,description TEXT NOT NULL DEFAULT '',status TEXT NOT NULL DEFAULT 'open',owner_text TEXT,date TEXT,payload_json TEXT NOT NULL DEFAULT '{}',result_id TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE artifact_links(id TEXT PRIMARY KEY,artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,related_artifact_id TEXT NOT NULL REFERENCES artifacts(id) ON DELETE CASCADE,relation TEXT NOT NULL,provenance_ref TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE analysis_runs(id TEXT PRIMARY KEY,meeting_id TEXT REFERENCES meetings(id) ON DELETE CASCADE,task TEXT NOT NULL,input_revision INTEGER NOT NULL,note_revision INTEGER,watermark INTEGER NOT NULL,provider_fingerprint TEXT NOT NULL DEFAULT '',model_fingerprint TEXT NOT NULL DEFAULT '',prompt_version TEXT NOT NULL DEFAULT '',schema_fingerprint TEXT NOT NULL DEFAULT '',policy_hash TEXT NOT NULL,status TEXT NOT NULL,usage_json TEXT,error_json TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE analysis_results(id TEXT PRIMARY KEY,run_id TEXT NOT NULL REFERENCES analysis_runs(id) ON DELETE CASCADE,kind TEXT NOT NULL,payload_json TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'candidate' CHECK(state IN('candidate','promoted','superseded')),language TEXT NOT NULL DEFAULT 'auto',content_hash TEXT NOT NULL,promoted_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE ask_answers(id TEXT PRIMARY KEY,query TEXT NOT NULL,scope_json TEXT NOT NULL,retrieval_fingerprint TEXT NOT NULL,answer TEXT NOT NULL,insufficient_evidence INTEGER NOT NULL,provider_fingerprint TEXT NOT NULL DEFAULT '',model_fingerprint TEXT NOT NULL DEFAULT '',prompt_version TEXT NOT NULL DEFAULT '',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE citations(id TEXT PRIMARY KEY,owner_result_id TEXT REFERENCES analysis_results(id) ON DELETE CASCADE,owner_ask_answer_id TEXT REFERENCES ask_answers(id) ON DELETE CASCADE,owner_digest_run_id TEXT,owner_note_id TEXT REFERENCES notes(id) ON DELETE CASCADE,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,source_utterance_id TEXT REFERENCES utterances(id) ON DELETE CASCADE,source_note_id TEXT REFERENCES notes(id) ON DELETE CASCADE,start_ms INTEGER,end_ms INTEGER,quote_snapshot TEXT,source_revision INTEGER NOT NULL,stale INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',CHECK((owner_result_id IS NOT NULL)+(owner_ask_answer_id IS NOT NULL)+(owner_digest_run_id IS NOT NULL)+(owner_note_id IS NOT NULL)=1),CHECK((source_utterance_id IS NOT NULL)+(source_note_id IS NOT NULL)=1));
CREATE TABLE entity_sources(id TEXT PRIMARY KEY,action_id TEXT REFERENCES actions(id) ON DELETE CASCADE,question_id TEXT REFERENCES questions(id) ON DELETE CASCADE,artifact_id TEXT REFERENCES artifacts(id) ON DELETE CASCADE,important_moment_id TEXT REFERENCES important_moments(id) ON DELETE CASCADE,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,utterance_id TEXT REFERENCES utterances(id) ON DELETE CASCADE,note_id TEXT REFERENCES notes(id) ON DELETE CASCADE,source_revision INTEGER NOT NULL,start_ms INTEGER,end_ms INTEGER,quote_snapshot TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',CHECK((action_id IS NOT NULL)+(question_id IS NOT NULL)+(artifact_id IS NOT NULL)+(important_moment_id IS NOT NULL)=1),CHECK((utterance_id IS NOT NULL)+(note_id IS NOT NULL)=1));
CREATE TABLE integration_connections(id TEXT PRIMARY KEY,kind TEXT NOT NULL,display_name TEXT NOT NULL DEFAULT '',endpoint TEXT NOT NULL DEFAULT '',nonsecret_settings_json TEXT NOT NULL DEFAULT '{}',vault_refs_json TEXT NOT NULL DEFAULT '{}',scopes_json TEXT NOT NULL DEFAULT '[]',state TEXT NOT NULL DEFAULT 'disconnected',consent_revision INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE deliveries(id TEXT PRIMARY KEY,integration_connection_id TEXT NOT NULL REFERENCES integration_connections(id) ON DELETE CASCADE,owner_result_id TEXT REFERENCES analysis_results(id) ON DELETE CASCADE,owner_digest_run_id TEXT,operation_id TEXT NOT NULL UNIQUE,request_hash TEXT NOT NULL,state TEXT NOT NULL DEFAULT 'prepared',acknowledged_at INTEGER,safe_error_json TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',CHECK((owner_result_id IS NOT NULL)+(owner_digest_run_id IS NOT NULL)=1));
CREATE TABLE memory_segments(id TEXT PRIMARY KEY,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,work_package_id TEXT REFERENCES work_packages(id) ON DELETE CASCADE,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,result_id TEXT NOT NULL REFERENCES analysis_results(id) ON DELETE CASCADE,input_revision INTEGER NOT NULL,summary TEXT NOT NULL,compressed_from_json TEXT,stale INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE briefings(id TEXT PRIMARY KEY,meeting_id TEXT REFERENCES meetings(id) ON DELETE CASCADE,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,work_package_id TEXT REFERENCES work_packages(id) ON DELETE CASCADE,kind TEXT NOT NULL,scope_hash TEXT NOT NULL,input_fingerprint TEXT NOT NULL,result_id TEXT NOT NULL REFERENCES analysis_results(id) ON DELETE CASCADE,stale INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE media_segments(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,source_id TEXT REFERENCES capture_sources(id) ON DELETE CASCADE,relative_path TEXT NOT NULL,codec TEXT NOT NULL,rate INTEGER NOT NULL,channels INTEGER NOT NULL,start_ms INTEGER NOT NULL,duration_ms INTEGER NOT NULL,sample_count INTEGER NOT NULL,pre_skip_samples INTEGER NOT NULL DEFAULT 0,bytes INTEGER NOT NULL,sha256 TEXT NOT NULL,state TEXT NOT NULL,retain_until INTEGER,pinned INTEGER NOT NULL DEFAULT 0,origin TEXT NOT NULL DEFAULT 'original',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX media_retention ON media_segments(state,retain_until);
CREATE TABLE import_assets(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,original_name TEXT NOT NULL,hash TEXT NOT NULL,duration_ms INTEGER NOT NULL,decoded_profile_json TEXT NOT NULL DEFAULT '{}',retained INTEGER NOT NULL DEFAULT 0,origin_metadata_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE vocabulary_terms(id TEXT PRIMARY KEY,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,term TEXT NOT NULL,normalized_term TEXT NOT NULL DEFAULT '',pronunciation_hint TEXT,aliases_json TEXT NOT NULL DEFAULT '[]',locale TEXT,priority INTEGER NOT NULL DEFAULT 0,enabled INTEGER NOT NULL DEFAULT 1,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE UNIQUE INDEX vocabulary_scope ON vocabulary_terms(COALESCE(project_id,''),normalized_term,COALESCE(locale,''));
CREATE TABLE provider_connections(id TEXT PRIMARY KEY,adapter_id TEXT NOT NULL,adapter_version TEXT NOT NULL DEFAULT '1',display_name TEXT NOT NULL DEFAULT '',endpoint TEXT NOT NULL DEFAULT '',region TEXT,auth_kind TEXT NOT NULL DEFAULT 'none',secret_ref TEXT,nonsecret_settings_json TEXT NOT NULL DEFAULT '{}',declared_execution TEXT NOT NULL DEFAULT 'unknown',capability_fingerprint TEXT NOT NULL DEFAULT '',consent_revision INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE model_profiles(id TEXT PRIMARY KEY,connection_id TEXT REFERENCES provider_connections(id) ON DELETE CASCADE,role TEXT NOT NULL,model_id TEXT NOT NULL,artifact_fingerprint TEXT,options_json TEXT NOT NULL DEFAULT '{}',resolved_capabilities_json TEXT NOT NULL DEFAULT '{}',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE task_policies(id TEXT PRIMARY KEY,task TEXT NOT NULL,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,model_profile_id TEXT REFERENCES model_profiles(id) ON DELETE CASCADE,fallback_ids_json TEXT NOT NULL DEFAULT '[]',language TEXT NOT NULL DEFAULT 'auto',token_limit INTEGER NOT NULL DEFAULT 8192,deadline_ms INTEGER NOT NULL DEFAULT 60000,budget_limit REAL NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE consents(id TEXT PRIMARY KEY,purpose TEXT NOT NULL,destination_fingerprint TEXT NOT NULL,data_classes_json TEXT NOT NULL,scope TEXT NOT NULL,accepted_at INTEGER NOT NULL,revoked_at INTEGER,policy_version TEXT NOT NULL DEFAULT '1',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE calendar_connections(id TEXT PRIMARY KEY,provider TEXT NOT NULL,account_label TEXT NOT NULL DEFAULT '',secret_refs_json TEXT NOT NULL DEFAULT '{}',selected_calendar_ids_json TEXT NOT NULL DEFAULT '[]',scope_json TEXT NOT NULL DEFAULT '[]',last_sync_at INTEGER,state TEXT NOT NULL DEFAULT 'disconnected',created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE calendar_events(id TEXT PRIMARY KEY,connection_id TEXT NOT NULL REFERENCES calendar_connections(id) ON DELETE CASCADE,external_id TEXT NOT NULL,series_id TEXT,occurrence_key TEXT NOT NULL,title TEXT NOT NULL DEFAULT '',start_utc INTEGER NOT NULL,end_utc INTEGER NOT NULL,original_timezone TEXT NOT NULL DEFAULT 'UTC',attendees_json TEXT NOT NULL DEFAULT '[]',join_url TEXT,canceled INTEGER NOT NULL DEFAULT 0,content_hash TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}',UNIQUE(connection_id,occurrence_key));
CREATE TABLE issue_links(id TEXT PRIMARY KEY,action_id TEXT NOT NULL REFERENCES actions(id) ON DELETE CASCADE,connection_id TEXT NOT NULL REFERENCES integration_connections(id) ON DELETE CASCADE,repository TEXT NOT NULL,operation_id TEXT NOT NULL UNIQUE,remote_number INTEGER,remote_url TEXT,state TEXT NOT NULL DEFAULT 'prepared',submitted_payload_hash TEXT NOT NULL,marker TEXT NOT NULL,last_checked_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE digest_schedules(id TEXT PRIMARY KEY,project_id TEXT NOT NULL REFERENCES projects(id) ON DELETE CASCADE,timezone TEXT NOT NULL DEFAULT 'UTC',weekday INTEGER NOT NULL DEFAULT 4,local_time TEXT NOT NULL DEFAULT '16:00',enabled INTEGER NOT NULL DEFAULT 0,delivery_json TEXT NOT NULL DEFAULT '{}',last_period_end INTEGER,next_run_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE digest_runs(id TEXT PRIMARY KEY,schedule_id TEXT NOT NULL REFERENCES digest_schedules(id) ON DELETE CASCADE,period_start INTEGER NOT NULL,period_end INTEGER NOT NULL,input_fingerprint TEXT NOT NULL,result_id TEXT REFERENCES analysis_results(id) ON DELETE SET NULL,status TEXT NOT NULL,delivery_state TEXT NOT NULL DEFAULT 'local',preview INTEGER NOT NULL DEFAULT 0,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE UNIQUE INDEX scheduled_digest_boundary ON digest_runs(schedule_id,period_end) WHERE preview=0;
CREATE TABLE jobs(id TEXT PRIMARY KEY,kind TEXT NOT NULL,meeting_id TEXT REFERENCES meetings(id) ON DELETE CASCADE,idempotency_key TEXT NOT NULL UNIQUE,stage TEXT NOT NULL,payload_json TEXT NOT NULL,status TEXT NOT NULL DEFAULT 'queued',attempts INTEGER NOT NULL DEFAULT 0,available_at INTEGER NOT NULL,lease_owner TEXT,lease_until INTEGER,heartbeat_at INTEGER,cancellation_requested INTEGER NOT NULL DEFAULT 0,error_json TEXT,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE INDEX job_ready ON jobs(status,available_at);
CREATE TABLE process_runs(id TEXT PRIMARY KEY,pid INTEGER NOT NULL,started_at INTEGER NOT NULL,heartbeat_at INTEGER NOT NULL,ended_at INTEGER);
CREATE TABLE outbox_events(seq INTEGER PRIMARY KEY AUTOINCREMENT,event_id TEXT NOT NULL UNIQUE,event_type TEXT NOT NULL,entity_id TEXT,meeting_id TEXT REFERENCES meetings(id) ON DELETE CASCADE,revision INTEGER,payload_json TEXT NOT NULL,created_at INTEGER NOT NULL);
CREATE TABLE idempotency_records(key TEXT NOT NULL,operation TEXT NOT NULL,request_hash TEXT NOT NULL,response_json TEXT NOT NULL,expires_at INTEGER NOT NULL,PRIMARY KEY(key,operation));
CREATE TABLE undo_commands(id TEXT PRIMARY KEY,entity_scope TEXT NOT NULL,expected_revision INTEGER NOT NULL,inverse_patch_json TEXT NOT NULL,expires_at INTEGER NOT NULL,applied_at INTEGER,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE search_chunks(id TEXT PRIMARY KEY,meeting_id TEXT NOT NULL REFERENCES meetings(id) ON DELETE CASCADE,run_id TEXT NOT NULL REFERENCES transcript_runs(id) ON DELETE CASCADE,start_utterance_id TEXT NOT NULL REFERENCES utterances(id) ON DELETE CASCADE,end_utterance_id TEXT NOT NULL REFERENCES utterances(id) ON DELETE CASCADE,text TEXT NOT NULL,source_revision INTEGER NOT NULL,chunker_version TEXT NOT NULL,content_hash TEXT NOT NULL,start_ms INTEGER NOT NULL,end_ms INTEGER NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE VIRTUAL TABLE search_fts USING fts5(chunk_id UNINDEXED,text,tokenize='unicode61 remove_diacritics 2');
CREATE TRIGGER search_delete AFTER DELETE ON search_chunks BEGIN DELETE FROM search_fts WHERE chunk_id=old.id; END;
CREATE TABLE embedding_generations(id TEXT PRIMARY KEY,fingerprint TEXT NOT NULL UNIQUE,dimensions INTEGER NOT NULL,preparation_version TEXT NOT NULL,normalization TEXT NOT NULL,state TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE chunk_embeddings(generation_id TEXT NOT NULL REFERENCES embedding_generations(id) ON DELETE CASCADE,chunk_id TEXT NOT NULL REFERENCES search_chunks(id) ON DELETE CASCADE,vector BLOB NOT NULL,content_hash TEXT NOT NULL,PRIMARY KEY(generation_id,chunk_id));
CREATE TABLE legacy_imports(id TEXT PRIMARY KEY,source_fingerprint TEXT NOT NULL UNIQUE,source_schema TEXT NOT NULL,imported_at INTEGER NOT NULL,report_json TEXT NOT NULL,id_map_object_ref TEXT REFERENCES objects(id) ON DELETE SET NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,extensions_json TEXT NOT NULL DEFAULT '{}');
CREATE TABLE workflow_documents(collection TEXT NOT NULL,id TEXT NOT NULL,meeting_id TEXT REFERENCES meetings(id) ON DELETE CASCADE,project_id TEXT REFERENCES projects(id) ON DELETE CASCADE,state TEXT,status TEXT,payload_json TEXT NOT NULL,created_at INTEGER NOT NULL,updated_at INTEGER NOT NULL,revision INTEGER NOT NULL DEFAULT 1,PRIMARY KEY(collection,id));
PRAGMA user_version=1;
